This sometimes prints garbage after 'olleh'. What's going on?

```c
#include <stdio.h>
#include <string.h>
#include <stdlib.h>

char *reverse(const char *s) {
    size_t n = strlen(s);
    char *out = malloc(n);
    for (size_t i = 0; i < n; i++)
        out[i] = s[n - 1 - i];
    return out;
}

int main(void) {
    char *r = reverse("hello");
    printf("%s\n", r);
    return 0;
}
```

